// Arma la agenda del día a partir de los eventos de Google Calendar
const eventos = $input.all()
  .map((item) => item.json)
  .filter((e) => e.id && e.status !== 'cancelled');

const hoy = $now.setLocale('es').toFormat("cccc d 'de' LLLL");
const hora = (iso) => DateTime.fromISO(iso).toFormat('HH:mm');

let minutos = 0;
const lineas = eventos.map((e) => {
  const lugar = e.hangoutLink ? ' · ' + e.hangoutLink : e.location ? ' · ' + e.location : '';
  if (e.start?.date) return '• Todo el día: ' + (e.summary || 'Sin título') + lugar;
  minutos += DateTime.fromISO(e.end.dateTime).diff(DateTime.fromISO(e.start.dateTime), 'minutes').minutes;
  return '• ' + hora(e.start.dateTime) + '–' + hora(e.end.dateTime) + '  ' + (e.summary || 'Sin título') + lugar;
});

const ocupado = Math.floor(minutos / 60) + ' h ' + Math.round(minutos % 60) + ' min';
const asunto = eventos.length === 0
  ? 'Tu agenda de hoy: sin reuniones'
  : 'Tu agenda de hoy: ' + eventos.length + (eventos.length === 1 ? ' evento' : ' eventos');
const cuerpo = eventos.length === 0
  ? 'Hoy, ' + hoy + ', no tienes eventos en el calendario. Buen día para avanzar en lo importante.'
  : ['Agenda del ' + hoy + ':', '', ...lineas, '', 'Tiempo en reuniones: ' + ocupado + '.'].join('\n');

return [{ json: { asunto, cuerpo } }];
